// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL     string
	Middlewares []MiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/banks", wrapper.GetBanks)

	router.Post(options.BaseURL+"/login", wrapper.PostLogin)

	router.Post(options.BaseURL+"/signup", wrapper.PostSignup)

	router.Get(options.BaseURL+"/user/:id", wrapper.GetUserId)

	router.Get(options.BaseURL+"/user/:id/accounts", wrapper.GetUserIdAccounts)

	router.Post(options.BaseURL+"/user/:id/accounts", wrapper.PostUserIdAccounts)

	router.Delete(options.BaseURL+"/user/:id/accounts/:account_id", wrapper.DeleteUserIdAccountsAccountId)

	router.Get(options.BaseURL+"/user/:id/accounts/:account_id", wrapper.GetUserIdAccountsAccountId)

	router.Get(options.BaseURL+"/user/:id/categories", wrapper.GetUserIdCategories)

	router.Post(options.BaseURL+"/user/:id/categories", wrapper.PostUserIdCategories)

	router.Delete(options.BaseURL+"/user/:id/categories/:category_id", wrapper.DeleteUserIdCategoriesCategoryId)

	router.Get(options.BaseURL+"/user/:id/categories/:category_id", wrapper.GetUserIdCategoriesCategoryId)

	router.Patch(options.BaseURL+"/user/:id/categories/:category_id", wrapper.PatchUserIdCategoriesCategoryId)

	router.Post(options.BaseURL+"/user/:id/categories/:category_id/rules", wrapper.PostUserIdCategoriesCategoryIdRules)

	router.Delete(options.BaseURL+"/user/:id/categories/:category_id/rules/:rule_id", wrapper.DeleteUserIdCategoriesCategoryIdRulesRuleId)

	router.Patch(options.BaseURL+"/user/:id/categories/:category_id/rules/:rule_id", wrapper.PatchUserIdCategoriesCategoryIdRulesRuleId)

	router.Get(options.BaseURL+"/user/:id/summary/accounts", wrapper.GetUserIdSummaryAccounts)

	router.Get(options.BaseURL+"/user/:id/summary/balance", wrapper.GetUserIdSummaryBalance)

	router.Get(options.BaseURL+"/user/:id/summary/categories", wrapper.GetUserIdSummaryCategories)

	router.Get(options.BaseURL+"/user/:id/transactions", wrapper.GetUserIdTransactions)

	router.Post(options.BaseURL+"/user/:id/transactions", wrapper.PostUserIdTransactions)

	router.Post(options.BaseURL+"/user/:id/transactions/bulk", wrapper.PostUserIdTransactionsBulk)

	router.Post(options.BaseURL+"/user/:id/transactions/bulk/delete", wrapper.PostUserIdTransactionsBulkDelete)

	router.Post(options.BaseURL+"/user/:id/transactions/bulk/finalise", wrapper.PostUserIdTransactionsBulkFinalise)

	router.Delete(options.BaseURL+"/user/:id/transactions/:transaction_id", wrapper.DeleteUserIdTransactionsTransactionId)

	router.Get(options.BaseURL+"/user/:id/transactions/:transaction_id", wrapper.GetUserIdTransactionsTransactionId)

	router.Patch(options.BaseURL+"/user/:id/transactions/:transaction_id", wrapper.PatchUserIdTransactionsTransactionId)

}

